input.old_string:
export function lock(): void {
  if (locked) return;
  if (instance) return;
  try {
    instance = new Gtk4SessionLock.Instance();
    attachSignals(instance);
    const ok = instance.lock();
    if (!ok) {
      logError("instance.lock() returned false");
      if (instance) {
        instance = null;
      }
    }
  } catch (e) {
    logError("lock() threw", e);
    instance = null;
  }
}

export function unlock(): void {
  if (!instance) {
    logError("unlock() called with no active lock instance");
    return;
  }
  try {
    instance.unlock();
  } catch (e) {
    logError("instance.unlock() threw", e);
  }
}

