export function lock(): void {
  if (locked) return;
  if (instance) return;
  retryTimer.cancel();
  attemptCount = 1;
  attemptStartMs = Date.now();
  tryAcquireLock();
}

export function unlock(): void {
  retryTimer.cancel();
  attemptCount = 0;
  if (!instance) {
    logError("unlock() called with no active lock instance");
    return;
  }
  try {
    instance.unlock();
  } catch (e) {
    logError("instance.unlock() threw", e);
  }
}
